'use client';
import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { Home, CalendarDays, Wallet, Target, BookOpen, SlidersHorizontal, Bell, Plus, ChevronLeft, ChevronRight, X, Check, Trash2, Pencil, ImagePlus, LogOut, ShieldCheck, Menu, Repeat2, Clock, RefreshCw, Heart, CheckCircle2 } from 'lucide-react';
import { SoftSelect, ConfirmationHost, askConfirmation } from './soft-controls';
import { PhotoGallery, PhotoPicker } from './photo-controls';
import { Flower, type User } from './auth-screen';
import { api, ApiError, vnd, dateLabel } from '@/lib/client';
import { emptyState, dateSchema, todayVN, addDays, weekStart, shiftMonth, daysBetween, tasksOn, completion, finances, goalProgress, type State, type Command, type Occurrence, type Task, type Entry, type Goal, type Settings } from '@/lib/domain';
function initialDay(fallback: string) { if (typeof window === 'undefined') return fallback; const parsed = dateSchema.safeParse(new URLSearchParams(location.search).get('day')); return parsed.success ? parsed.data : fallback; }
type Page = 'dashboard' | 'calendar' | 'finance' | 'goals' | 'journal' | 'settings' | 'account';
type AppContext = { setSettingsPreview: (s: Settings | null) => void; state: State; today: string; busy: boolean; save: (command: Command) => Promise<void>; notify: (message: string) => void; preview: boolean };
const Context = createContext<AppContext>(null!); const useApp = () => useContext(Context);
const nav = [{ id: 'dashboard', label: 'Dashboard', icon: Home }, { id: 'calendar', label: 'Lịch của Mihu', icon: CalendarDays }, { id: 'finance', label: 'Tài chính', icon: Wallet }, { id: 'goals', label: 'Mục tiêu', icon: Target }, { id: 'journal', label: 'Nhật ký', icon: BookOpen }] as const;
const uid = () => crypto.randomUUID(); const asset = (id: string) => '/api/assets?id=' + encodeURIComponent(id);
export function Panel({ title, action, children, className = '' }: { title?: string; action?: ReactNode; children: ReactNode; className?: string }) { return <section className={'panel ' + className}>{title && <div className="section-head"><h2>{title}</h2>{action}</div>}{children}</section>; }
export function Empty({ icon: Icon = Flower, title, children, action }: { icon?: React.ElementType; title: string; children?: ReactNode; action?: ReactNode }) { return <div className="empty"><Icon size={30} /><h3>{title}</h3>{children && <p>{children}</p>}{action}</div>; }
export function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { const ref = useRef<HTMLDialogElement>(null); useEffect(() => { const d = ref.current; d?.showModal(); return () => d?.close(); }, []); return <dialog ref={ref} className="modal" onCancel={onClose} onClick={e => { if (e.target === e.currentTarget) onClose(); }}><div className="modal-head"><h2>{title}</h2><button className="icon-button" aria-label="Đóng" onClick={onClose}><X size={22} /></button></div>{children}</dialog>; }
export function Submit({ children = 'Lưu lại' }: { children?: ReactNode }) { const { busy } = useApp(); return <button className="button primary" disabled={busy} type="submit">{busy ? 'Đang lưu…' : children}</button>; }
function Progress({ value }: { value: number }) { return <div className="progress" role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100}><span style={{ width: Math.min(100, Math.max(0, value)) + '%' }} /></div>; }
function Stat({ label, value, note, color }: { label: string; value: ReactNode; note: string; color?: string }) { return <div className={'stat ' + (color || '')}><small>{label}</small><strong>{value}</strong><small>{note}</small></div>; }
export function Corner({ user, onLogout, preview = false }: { user: User | null; onLogout: () => void; preview?: boolean }) {
    const [state, setState] = useState<State>(emptyState); const [settingsPreview, setSettingsPreview] = useState<Settings | null>(null); const [systemDark, setSystemDark] = useState(false); useEffect(() => { const m = matchMedia("(prefers-color-scheme: dark)"); const update = () => setSystemDark(m.matches); update(); m.addEventListener("change", update); return () => m.removeEventListener("change", update); }, []); const version = useRef(0); const [loading, setLoading] = useState(!preview); const [busy, setBusy] = useState(false); const busyRef = useRef(false); const [error, setError] = useState(''); const [toast, setToast] = useState(''); const [page, setPage] = useState<Page>(() => typeof window !== 'undefined' && new URLSearchParams(location.search).has('day') ? 'calendar' : 'dashboard'); const [more, setMore] = useState(false); const [notifications, setNotifications] = useState(false); const [today, setToday] = useState(todayVN); const operation = useRef<{ signature: string; id: string } | null>(null);
    const reload = async () => { const r = await api<{ state: State; version: number }>('/api/state'); setState(r.state); version.current = r.version; };
    useEffect(() => { if (preview) return; reload().catch(e => setError(e.message)).finally(() => setLoading(false)); const refresh = () => { if (!busyRef.current) reload().catch(() => { }); }; window.addEventListener('focus', refresh); return () => window.removeEventListener('focus', refresh); }, [preview]);
    useEffect(() => { const t = setInterval(() => setToday(todayVN()), 60000); return () => clearInterval(t); }, []);
    useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(''), 5000); return () => clearTimeout(t); }, [toast]);
    useEffect(() => { if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => { }); }, []);
    async function save(command: Command) { if (preview) throw new Error('Đây là bản xem bố cục. Hãy đăng nhập để lưu dữ liệu thật.'); if (busyRef.current) throw new Error('Mihu chờ thao tác trước lưu xong nhé.'); busyRef.current = true; setBusy(true); const signature = JSON.stringify(command); if (operation.current?.signature !== signature) operation.current = { signature, id: uid() }; try { let r; try { r = await api<{ state: State; version: number }>('/api/state', { version: version.current, operation: operation.current.id, command }); } catch (e) { if (e instanceof ApiError && e.details?.rollovers && await askConfirmation(e.message)) { r = await api<{ state: State; version: number }>('/api/state', { version: version.current, operation: uid(), command: { ...command, confirmRollover: true } }); } else { if (e instanceof ApiError && e.details?.reload) await reload(); throw e; } } setState(r.state); version.current = r.version; operation.current = null; setToast('Đã lưu vào nhật ký.'); } finally { setBusy(false); busyRef.current = false; } }
    async function logout() { try { if (!preview) await api('/api/auth', { action: 'logout' }); navigator.serviceWorker?.controller?.postMessage({ type: 'logout' }); onLogout(); } catch (e) { setError((e as Error).message); } }
    const changePage = async (p: Page) => { if (settingsPreview && JSON.stringify(settingsPreview) !== JSON.stringify(state.settings) && !await askConfirmation('Mihu muốn bỏ các thay đổi chưa lưu?')) return; setSettingsPreview(null); setPage(p); setMore(false); window.scrollTo({ top: 0 }); };
    const activeSettings = settingsPreview || state.settings; const theme = activeSettings.theme === 'system' ? (systemDark ? 'dark' : 'light') : activeSettings.theme; const sunflowerPage = page === 'dashboard' || page === 'account'; const titles: Record<Page, string> = { dashboard: 'Bonjour Mihuuu', calendar: 'Lịch của Mihu', finance: 'Ví của Mihu', goals: 'Từng chút một, đến gần điều Mihu muốn', journal: 'Nhật ký của Mihu', settings: 'Cá nhân hóa góc nhỏ', account: 'Tài khoản của Mihu' };
    const subtitles: Record<Page, string> = { dashboard: dateLabel(today), calendar: 'Dành thời gian cho những điều quan trọng.', finance: 'Biết tiền đang ở đâu, để mỗi ngày nhẹ đầu hơn.', goals: 'Không cần vội. Mỗi bước nhỏ đều được tính.', journal: 'Hôm nay Mihu cảm thấy thế nào?', settings: '', account: 'Góc an toàn, dành riêng cho Mihu.' };
    return <Context.Provider value={{ state, today, busy, save, notify: setToast, preview, setSettingsPreview }}><div className={'corner ' + (sunflowerPage ? 'sunny ' : '') + (activeSettings.accent === 'yellow' ? 'yellow-accent ' : '') + 'theme-' + theme}><ConfirmationHost /><aside className="sidebar"><a href="#" onClick={e => { e.preventDefault(); changePage('dashboard'); }} className="brand"><Flower /><strong>Mihu’s<br />Corner</strong></a><span className="nav-caption">GÓC NHỎ CỦA MIHU</span><nav>{nav.map(n => <button key={n.id} className={'nav-item ' + (page === n.id ? 'active' : '')} onClick={() => changePage(n.id)}><n.icon size={21} />{n.label}</button>)}</nav><div className="sidebar-note"><Flower /><p>{state.settings.quote}</p></div><div className="sidebar-bottom"><button className={'nav-item ' + (page === 'settings' ? 'active' : '')} onClick={() => changePage('settings')}><SlidersHorizontal size={20} />Cá nhân hóa</button><button className="account-link" onClick={() => changePage('account')}><span className="avatar">{state.settings.avatar ? <img src={asset(state.settings.avatar)} alt="" /> : 'M'}</span><span><strong>Mihu</strong><small>Góc nhỏ của Mihu</small></span></button></div></aside><main className="main-content">{preview && <div className="preview-banner">Bản xem bố cục · Dữ liệu trống, chưa đăng nhập <button className="text-button" onClick={onLogout}>Trang đăng nhập</button></div>}<header className="page-header"><div><h1>{titles[page]}</h1><p>{subtitles[page]}</p></div><div className="header-actions">{page === 'dashboard' ? <button className="button" onClick={() => changePage('settings')}><SlidersHorizontal size={16} />Tùy chỉnh góc nhỏ</button> : <span className="date-pill">{dateLabel(today, true)}</span>}<button className="icon-button" aria-label="Nhắc việc" onClick={() => setNotifications(true)}><Bell size={23} /></button></div></header>{error && <div className="error-banner" role="alert">{error}<button className="text-button" onClick={() => { setLoading(true); reload().then(() => setError('')).catch(e => setError(e.message)).finally(() => setLoading(false)); }}>Thử lại</button></div>}{loading ? <Empty title="Đang mở Mihu's corner" /> : <div className="page-enter" key={page}>{page === 'dashboard' && <Dashboard navigate={changePage} />} {page === 'calendar' && <Calendar />}{page === 'finance' && <Finance />}{page === 'goals' && <Goals />}{page === 'journal' && <Journal />}{page === 'settings' && <Personalize />}{page === 'account' && <Account user={user} logout={logout} openNotifications={() => setNotifications(true)} />}</div>}<footer className="page-footer">Design and Dev by Mnhat. <Flower /></footer></main><nav className="mobile-nav" aria-label="Điều hướng trên điện thoại">{nav.slice(0, 3).map(n => <button key={n.id} className={page === n.id ? 'active' : ''} onClick={() => changePage(n.id)}><n.icon size={22} /><span>{n.id === 'dashboard' ? 'Góc nhỏ' : n.id === 'calendar' ? 'Lịch' : 'Chi tiêu'}</span></button>)}<button className={more ? 'active' : ''} onClick={() => setMore(true)}><Menu size={22} /><span>Thêm</span></button></nav>{more && <Modal title="Góc nhỏ của Mihu" onClose={() => setMore(false)}><div className="more-menu">{nav.slice(3).map(n => <button className="nav-item" key={n.id} onClick={() => changePage(n.id)}><n.icon size={22} />{n.label}</button>)}<button className="nav-item" onClick={() => changePage('settings')}><SlidersHorizontal />Cá nhân hóa</button><button className="nav-item" onClick={() => changePage('account')}><ShieldCheck />Tài khoản</button></div></Modal>}{notifications && <Modal title="Nhắc việc cho Mihu" onClose={() => setNotifications(false)}><Notifications /></Modal>}{toast && <div className="toast" role="status"><CheckCircle2 size={20} />{toast}</div>}</div></Context.Provider>;
}
function Dashboard({ navigate }: { navigate: (p: Page) => void }) { const { state, today } = useApp(); const [newTask, setNewTask] = useState(false); const ts = tasksOn(state, today); const c = completion(ts, today); const month = today.slice(0, 7); const f = finances(state, month); const week = daysBetween(weekStart(today), addDays(weekStart(today), 6)); const show = (k: string) => !state.settings.hidden.includes(k); return <div className="stack"><section className="welcome-banner"><div><span className="eyebrow">GÓC NẮNG HÔM NAY</span><h2>Gieo một việc nhỏ,<br />gặt một ngày vui.</h2><p>Mihu không cần làm tất cả.<br />Chỉ cần bắt đầu từ một điều nhỏ thôi.</p><button className="button yellow" onClick={() => setNewTask(true)}><Plus size={17} />Thêm việc hôm nay</button></div><div className="banner-flowers"><Flower /><Flower /><Flower /></div></section><div className="stats-grid"><Stat label="VIỆC HÔM NAY" value={ts.length ? `${c.done} / ${c.total}` : '—'} note={ts.length ? 'việc đã hoàn thành' : 'Chưa có việc được lên lịch'} /><Stat label="NHỊP NGÀY CỦA MIHU" value={c.percent === null ? '—' : c.percent + '%'} note={c.percent === null ? 'Bắt đầu bằng một điều nhỏ' : 'Mỗi bước nhỏ đều đáng ghi nhận'} color={c.color} /><Stat label="SỐ TIỀN CÒN LẠI" value={f.configured ? vnd(f.remaining) : '—'} note={f.configured ? 'Trong tháng ' + month.slice(5) + ' · Đã chi ' + vnd(f.spent) : 'Chưa thiết lập tiền tiêu tháng này'} /></div><div className="dashboard-grid">{show('tasks') && <Panel title="Việc hôm nay" action={<button className="text-button" onClick={() => navigate('calendar')}>Xem lịch</button>}>{ts.length ? <TaskList tasks={ts} /> : <Empty icon={CalendarDays} title="Hôm nay còn là một trang mới">Mihu muốn dành thời gian cho điều gì?</Empty>}<button className="button yellow" onClick={() => setNewTask(true)}><Plus size={16} />Thêm việc</button></Panel>}{show('photos') && <Panel title="Một góc nhỏ, nhiều niềm vui" className="decor-panel"><PhotoGallery photos={state.settings.photos} onAdd={() => navigate('settings')} /><p className="quote">“{state.settings.quote}”</p></Panel>}{show('week') && <Panel title="Tuần này của Mihu" action={<button className="text-button" onClick={() => navigate('calendar')}>Tổng kết tuần</button>}><div className="week-strip">{week.map((d, i) => { const x = completion(tasksOn(state, d), d); return <div className={'day-chip ' + x.color} key={d}><small>{['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'][i]}</small><strong>{d > today || x.percent === null ? '—' : x.percent + '%'}</strong></div>; })}</div><p className="support-line">{c.message}</p></Panel>}{show('journal') && <Panel title="Một dòng cho hôm nay" action={<Heart size={19} />}><p>{state.journals[today]?.text || 'Có điều gì khiến Mihu mỉm cười hôm nay không?'}</p><button className="text-button" onClick={() => navigate('journal')}>{state.journals[today] ? 'Đọc lại nhật ký' : 'Viết một chút nhé'}</button></Panel>}{show('goals') && <Panel title="Điều Mihu đang hướng tới" action={<button className="text-button" onClick={() => navigate('goals')}>Xem mục tiêu</button>}>{state.goals.filter(g => g.start <= today && g.end >= today).length ? state.goals.filter(g => g.start <= today && g.end >= today).map(g => <div className="mini-goal" key={g.id}><div className="row spread"><span>{g.title}</span><small>{goalProgress(state, g)}%</small></div><Progress value={goalProgress(state, g)} /></div>) : <p>Chưa có mục tiêu đang thực hiện. Một điều nhỏ cũng là khởi đầu tốt.</p>}</Panel>}{show('finance') && <Panel title="Chi tiêu tháng này" action={<button className="text-button" onClick={() => navigate('finance')}>Mở ví nhỏ</button>}><div className="row spread"><span>Đã chi</span><strong>{f.configured || f.spent ? vnd(f.spent) : '—'}</strong></div><Progress value={f.configured ? f.percent : 0} /><p className="support-line">{f.configured ? `Tiền tiêu trong tháng: ${vnd(f.total)}` : 'Nhập khoản tiền đầu tháng để bắt đầu.'}</p></Panel>}</div>{newTask && <TaskForm date={today} onClose={() => setNewTask(false)} />}</div>; }
function TaskList({ tasks }: { tasks: Occurrence[] }) { const { save, busy, notify, today, state } = useApp(); const [edit, setEdit] = useState<Occurrence | null>(null); async function toggle(t: Occurrence) { try { await save({ type: 'task.toggle', id: t.id, on: t.occurrenceDate, done: !t.done }); const list = tasksOn(state, t.occurrenceDate).map(x => x.key === t.key ? { ...x, done: !t.done } : x); if (completion(list, t.occurrenceDate).percent === 100) notify('🌻 Mihu giỏi lắm! Hoàn thành 100% rồi!'); } catch (e) { notify((e as Error).message); } } return <><div className="task-list">{tasks.map(t => <div className={'task-row ' + (t.done ? 'done' : '')} key={t.key}><input type="checkbox" aria-label={'Hoàn thành ' + t.title} checked={t.done} disabled={busy || t.occurrenceDate > today} onChange={() => toggle(t)} /><button className="task-detail" onClick={() => setEdit(t)}><span>{t.title}</span><small>{t.time && `${t.time}${t.endTime ? ' – ' + t.endTime : ''} · `}{t.category}{t.reminder >= 0 && ` · Nhắc trước ${t.reminder} phút`}</small></button><span className={'priority ' + t.priority} title={'Ưu tiên ' + t.priority}>{t.repeat !== 'none' ? <Repeat2 size={14} /> : null}</span><button className="icon-button" aria-label={'Sửa ' + t.title} onClick={() => setEdit(t)}><Pencil size={15} /></button></div>)}</div>{edit && <TaskForm task={edit} date={edit.occurrenceDate} onClose={() => setEdit(null)} />}</>; }
function TaskForm({ task, date, onClose }: { task?: Occurrence; date: string; onClose: () => void }) {
    const { save, busy } = useApp(); const [error, setError] = useState(''); const [repeat, setRepeat] = useState(task?.repeat || 'none'); const [scope, setScope] = useState<'one' | 'future'>('one'); const [id] = useState(task?.id || uid); async function submit(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); const v = (k: string) => String(f.get(k) || ''); try { await save({ type: 'task.save', scope: task ? scope : 'all', on: date, task: { id, title: v('title'), date: v('date') || date, time: v('time'), endTime: v('endTime'), note: v('note'), category: v('category'), priority: v('priority') as Task['priority'], repeat: repeat as Task['repeat'], weekdays: f.getAll('weekdays').map(Number), until: v('until'), reminder: Number(v('reminder')) as Task['reminder'] } }); onClose(); } catch (e) { setError((e as Error).message); } }
    async function remove() { if (!task || !await askConfirmation(scope === 'one' ? 'Xóa việc này trong ngày đã chọn?' : 'Xóa việc này từ ngày đã chọn trở đi?')) return; try { await save({ type: 'task.delete', id: task.id, on: date, scope }); onClose(); } catch (e) { setError((e as Error).message); } }
    return <Modal title={task ? 'Chăm chút lại kế hoạch' : 'Thêm một việc nhỏ'} onClose={onClose}><form onSubmit={submit}><label className="field">Mihu muốn làm gì?<input autoFocus name="title" required maxLength={200} defaultValue={task?.title} placeholder="Một việc Mihu muốn hoàn thành…" /></label>{task && <label className="field">Áp dụng thay đổi<SoftSelect value={scope} onChange={e => setScope(e.target.value as typeof scope)}><option value="one">Chỉ ngày {dateLabel(date, true)}</option><option value="future">Ngày này và các lần sau</option></SoftSelect></label>}<div className="form-grid"><label className="field">Ngày<input name="date" type="date" required defaultValue={date} readOnly={!!task} /></label><label className="field">Mức ưu tiên<SoftSelect name="priority" defaultValue={task?.priority || 'medium'}><option value="low">Thấp</option><option value="medium">Vừa</option><option value="high">Cao</option></SoftSelect></label><label className="field">Bắt đầu<input name="time" type="time" defaultValue={task?.time} /></label><label className="field">Kết thúc<input name="endTime" type="time" defaultValue={task?.endTime} /></label><label className="field">Nhóm việc<input name="category" maxLength={60} defaultValue={task?.category || 'Cá nhân'} /></label><label className="field">Nhắc việc<SoftSelect name="reminder" defaultValue={task?.reminder ?? -1}><option value={-1}>Không nhắc</option>{[0, 5, 15, 30].map(n => <option key={n} value={n}>{n === 0 ? 'Đúng giờ' : `Trước ${n} phút`}</option>)}</SoftSelect></label></div><div className="form-grid"><label className="field">Lặp lại<SoftSelect value={repeat} disabled={!!task && scope === 'one'} onChange={e => setRepeat(e.target.value as typeof repeat)}><option value="none">Không lặp</option><option value="daily">Hằng ngày</option><option value="weekly">Các ngày trong tuần</option><option value="monthly">Cùng ngày mỗi tháng</option></SoftSelect></label>{repeat !== 'none' && <label className="field">Lặp đến ngày (không bắt buộc)<input type="date" name="until" defaultValue={task?.until} /></label>}</div>{repeat === 'weekly' && <div className="weekday-options">{[1, 2, 3, 4, 5, 6, 0].map((n, i) => <label key={n}><input type="checkbox" name="weekdays" value={n} defaultChecked={task?.weekdays.includes(n)} />{['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'][i]}</label>)}</div>}{repeat === 'monthly' && <p className="support-line">Tháng không có ngày này sẽ được bỏ qua.</p>}<label className="field">Ghi chú<textarea name="note" maxLength={4000} defaultValue={task?.note} placeholder="Một lời nhắc nhỏ…" /></label>{error && <p className="error-banner" role="alert">{error}</p>}<div className="form-actions">{task && <button type="button" disabled={busy} className="button danger" onClick={remove}><Trash2 size={16} />Xóa việc</button>}<button type="button" className="button" onClick={onClose}>Để sau</button><Submit /></div></form></Modal>;
}
function Calendar() { const { state, today } = useApp(); const [date, setDate] = useState(() => initialDay(today)); const [mode, setMode] = useState<'week' | 'month'>('week'); const [selected, setSelected] = useState(() => initialDay(today)); const [add, setAdd] = useState(false); const [recap, setRecap] = useState(false); const start = weekStart(date); const week = daysBetween(start, addDays(start, 6)); const month = date.slice(0, 7); const monthDays = daysBetween(weekStart(month + '-01'), addDays(weekStart(shiftMonth(month, 1) + '-01'), 6)); const shift = (n: number) => setDate(mode === 'week' ? addDays(date, n * 7) : shiftMonth(month, n) + '-01'); const selectedTasks = tasksOn(state, selected); const c = completion(selectedTasks, selected); return <div className="stack"><div className="toolbar"><div className="segmented"><button className={mode === 'week' ? 'active' : ''} onClick={() => setMode('week')}>Tuần</button><button className={mode === 'month' ? 'active' : ''} onClick={() => setMode('month')}>Tháng</button></div><div className="row"><button className="icon-button" aria-label="Kỳ trước" onClick={() => shift(-1)}><ChevronLeft /></button><strong>{mode === 'week' ? `${dateLabel(week[0], true)} – ${dateLabel(week[6], true)}` : `Tháng ${Number(month.slice(5))}, ${month.slice(0, 4)}`}</strong><button className="icon-button" aria-label="Kỳ sau" onClick={() => shift(1)}><ChevronRight /></button><button className="button" onClick={() => { setDate(today); setSelected(today); }}>Hôm nay</button></div><button className="button primary" onClick={() => setAdd(true)}><Plus size={17} />Thêm việc</button></div><Panel className="calendar-panel"><div className={'calendar-grid ' + mode}>{(mode === 'week' ? week : monthDays).map(d => { const ts = tasksOn(state, d); const x = completion(ts, d); return <button key={d} className={`calendar-day ${x.color} ${selected === d ? 'selected' : ''} ${d === today ? 'today' : ''} ${mode === 'month' && !d.startsWith(month) ? 'outside' : ''}`} onClick={() => setSelected(d)}><span className="day-heading"><small>{['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'][new Date(d + 'T12:00:00Z').getUTCDay()]}</small><strong>{Number(d.slice(8))}</strong></span>{ts.length ? <><span className="day-count">{x.done}/{x.total} việc</span><div className="day-tasks">{ts.slice(0, mode === 'week' ? 4 : 2).map(t => <span key={t.key} className={t.done ? 'checked' : ''}>{t.done ? '✓ ' : ''}{t.title}</span>)}{ts.length > (mode === 'week' ? 4 : 2) && <small>+{ts.length - (mode === 'week' ? 4 : 2)} việc</small>}</div>{d <= today && <span className="day-percent">{x.percent}%</span>}</> : <span className="day-empty">Chưa có việc</span>}</button>; })}</div></Panel><div className="calendar-bottom"><Panel title={'Ngày ' + dateLabel(selected)} action={<button className="text-button" onClick={() => setAdd(true)}><Plus size={16} />Thêm việc</button>}>{selectedTasks.length ? <TaskList tasks={selectedTasks} /> : <Empty icon={CalendarDays} title="Một khoảng trống cho điều Mihu muốn">Chạm “Thêm việc” để lên kế hoạch cho ngày này.</Empty>}{selected <= today && selectedTasks.length > 0 && <p className={'day-message ' + c.color}>{c.message}{selected === today ? ' Tiến độ hôm nay vẫn đang được cập nhật.' : ''}</p>}</Panel><Panel title="Nhịp tuần"><div className="legend"><span className="green">100% · Trọn vẹn</span><span className="yellow">80–99% · Rất tốt</span><span className="orange">50–79% · Tiến bộ</span><span className="pink">Dưới 50% · Cố gắng thêm</span><span className="neutral">Chưa có việc / chưa đến ngày</span></div><button className="button full" onClick={() => setRecap(true)}>Xem tổng kết tuần</button></Panel></div>{add && <TaskForm date={selected} onClose={() => setAdd(false)} />} {recap && <Modal title="Nhìn lại một tuần của Mihu" onClose={() => setRecap(false)}><WeekRecap days={week} /></Modal>}</div>; }
function WeekRecap({ days }: { days: string[] }) { const { state, today } = useApp(); const past = days.filter(d => d <= today); const ts = past.flatMap(d => tasksOn(state, d)); const c = completion(ts, past.at(-1) || today); const perfect = past.filter(d => completion(tasksOn(state, d), d).percent === 100).length; const goals = state.goals.filter(g => g.start <= days[6] && g.end >= days[0]); return <div className="stack"><p>{dateLabel(days[0])} – {dateLabel(days[6])}</p><div className="stats-grid"><Stat label="Đã hoàn thành" value={`${c.done}/${c.total}`} note="việc trong các ngày đã đến" /><Stat label="Tiến độ tuần" value={c.percent === null ? '—' : c.percent + '%'} note="Không tính ngày tương lai" /><Stat label="Ngày trọn vẹn" value={perfect} note="ngày hoàn thành 100%" /></div><p className="notice">{c.message}</p><h3>Việc còn dang dở</h3>{ts.filter(t => !t.done).length ? <TaskList tasks={ts.filter(t => !t.done)} /> : <p>Không có việc dang dở trong các ngày đã đến.</p>}<h3>Mục tiêu trong tuần</h3>{goals.length ? goals.map(g => <div key={g.id} className="mini-goal"><div className="row spread"><span>{g.title}</span><strong>{goalProgress(state, g)}%</strong></div><Progress value={goalProgress(state, g)} /></div>) : <p>Chưa có mục tiêu trong tuần này.</p>}</div>; }
function Finance() {
    const { state, today, save, busy, notify } = useApp(); const [month, setMonth] = useState(today.slice(0, 7)); const [form, setForm] = useState<'expense' | 'addition' | 'budget' | 'categories' | null>(null); const [edit, setEdit] = useState<Entry | undefined>(); const [category, setCategory] = useState(''); const [date, setDate] = useState(''); const [error, setError] = useState(''); const f = finances(state, month); const rows = state.entries.filter(e => e.date.startsWith(month) && (!category || e.category === category) && (!date || e.date === date)).sort((a, b) => b.date.localeCompare(a.date)); const expenses = state.entries.filter(e => e.date.startsWith(month) && e.kind === 'expense'); const groups = state.categories.map(c => ({ name: c, value: expenses.filter(e => e.category === c).reduce((a, e) => a + e.amount, 0) })).filter(c => c.value > 0); const colors = ['#ae476d', '#f4c64e', '#7bac95', '#829ccd', '#c797bf', '#d6926c']; let angle = 0; const gradient = groups.map((g, i) => { const start = angle; angle += g.value / f.spent * 100; return `${colors[i % colors.length]} ${start}% ${angle}%`; }).join(','); const previous = finances(state, shiftMonth(month, -1)); const rollover = state.rollovers[month];
    async function decide(accepted: boolean) { try { await save({ type: 'rollover.set', month, accepted }); } catch (e) { notify((e as Error).message); } }
    const changeMonth = (n: number) => { setMonth(shiftMonth(month, n)); setDate(''); };
    return <div className="stack"><div className="toolbar"><div className="row"><button className="icon-button" aria-label="Tháng trước" onClick={() => changeMonth(-1)}><ChevronLeft /></button><label><span className="sr-only">Tháng chi tiêu</span><input type="month" value={month} onChange={e => { if (e.target.value) { setMonth(e.target.value); setDate(''); } }} /></label><button className="icon-button" aria-label="Tháng sau" onClick={() => changeMonth(1)}><ChevronRight /></button></div><div className="row wrap"><button className="button" onClick={() => { setEdit(undefined); setForm('addition'); }}><Plus size={17} />Thêm tiền</button><button className="button primary" onClick={() => { setEdit(undefined); setForm('expense'); }}><Plus size={17} />Ghi khoản chi</button></div></div><div className="stats-grid"><Stat label="TIỀN TIÊU TRONG THÁNG" value={f.configured ? vnd(f.total) : '—'} note={f.configured ? `Đầu tháng ${vnd(f.initial ?? 0)} · Thêm ${vnd(f.added)}` : 'Chưa thiết lập khoản tiền đầu tháng'} /><Stat label="ĐÃ TIÊU" value={f.configured || f.spent ? vnd(f.spent) : '—'} note={f.spent ? `${expenses.length} khoản chi trong tháng` : 'Chưa có khoản chi nào'} /><Stat label="CÒN LẠI" value={f.configured ? vnd(f.remaining) : '—'} note={f.rollover ? `Gồm ${vnd(f.rollover)} từ tháng trước` : 'Khoản tiền Mihu còn có thể sử dụng'} color={f.remaining < 0 ? 'pink' : 'green'} /></div><div className="row wrap"><button className="text-button" onClick={() => { setError(''); setForm('budget'); }}><Pencil size={15} />{f.initial === null ? 'Nhập tiền đầu tháng' : 'Chỉnh tiền đầu tháng'}</button><button className="text-button" onClick={() => { setError(''); setForm('categories'); }}>Quản lý danh mục</button></div>{f.configured && (f.percent >= 80 || f.remaining < 0) && <div className={f.remaining < 0 ? 'error-banner' : 'notice'}>{f.remaining < 0 ? `Mihu đã chi vượt ${vnd(-f.remaining)}. Cùng xem lại những khoản tiếp theo nhé.` : f.percent >= 100 ? 'Mihu đã sử dụng hết tiền tiêu tháng này.' : `Mihu đã dùng ${f.percent}% tiền tháng này. Chú ý các khoản chi tiếp theo nhé.`}</div>}{previous.configured && month <= today.slice(0, 7) && <Panel title="Số dư từ tháng trước"><div className="row spread wrap"><p>{rollover ? rollover.accepted ? `Đã chuyển ${vnd(rollover.amount)} vào tháng này.` : 'Mihu đã chọn không chuyển số dư.' : `Tháng trước còn ${vnd(Math.max(0, previous.remaining))}. Mihu có muốn chuyển sang tháng này không?`}</p><div className="row"><button disabled={busy} className={'button ' + (rollover?.accepted ? 'primary' : '')} onClick={() => decide(true)}>Có, kết chuyển</button><button disabled={busy} className={'button ' + (rollover && !rollover.accepted ? 'primary' : '')} onClick={() => decide(false)}>Không chuyển</button></div></div></Panel>}<div className="finance-grid"><Panel title="Tiền đã đi đâu?" action={<span className="pill">Theo khoản đã chi</span>}>{groups.length ? <div className="chart-layout"><div className="donut" role="img" aria-label={'Tỷ trọng khoản chi: ' + groups.map(g => g.name + ' ' + Math.round(g.value / f.spent * 100) + '%').join(', ')} style={{ background: `conic-gradient(${gradient})` }}><div><small>Tổng đã chi</small><strong>{vnd(f.spent)}</strong></div></div><div className="chart-legend">{groups.map((g, i) => <div key={g.name}><span className="legend-dot" style={{ background: colors[i % colors.length] }} /><span>{g.name}<small>{vnd(g.value)}</small></span><strong>{(g.value / f.spent * 100).toFixed(1)}%</strong></div>)}</div></div> : <Empty icon={Wallet} title="Chưa có khoản chi">Biểu đồ sẽ xuất hiện khi Mihu ghi khoản chi đầu tiên.</Empty>}</Panel><Panel title="Nhịp chi tiêu"><div className="row spread"><span>Đã sử dụng</span><strong>{f.configured ? f.percent + '%' : '—'}</strong></div><Progress value={f.configured ? f.percent : 0} /><div className="money-breakdown"><div><span>Tiền đầu tháng</span><strong>{f.initial === null ? 'Chưa nhập' : vnd(f.initial)}</strong></div><div><span>Được thêm trong tháng</span><strong>{vnd(f.added)}</strong></div><div><span>Số dư kết chuyển</span><strong>{vnd(f.rollover)}</strong></div></div><p className="support-line">Mỗi khoản nhỏ đều giúp Mihu hiểu rõ ví tiền hơn.</p></Panel></div><Panel title="Những khoản trong tháng"><div className="filter-row"><label className="field">Danh mục<SoftSelect value={category} onChange={e => setCategory(e.target.value)}><option value="">Tất cả danh mục</option>{state.categories.map(c => <option key={c} value={c}>{c}</option>)}</SoftSelect></label><label className="field">Ngày<input type="date" value={date} onChange={e => setDate(e.target.value)} /></label>{date && <button className="text-button" onClick={() => setDate('')}>Bỏ lọc ngày</button>}</div>{rows.length ? <div className="transactions">{[...new Set(rows.map(e => e.date))].map(d => <section key={d}><div className="transaction-day"><strong>{dateLabel(d)}</strong><small>Đã chi {vnd(rows.filter(e => e.date === d && e.kind === 'expense').reduce((a, e) => a + e.amount, 0))}</small></div>{rows.filter(e => e.date === d).map(e => <div className="transaction" key={e.id}><span className={'transaction-icon ' + (e.kind === 'addition' ? 'green' : 'pink')}><Wallet size={20} /></span><div className="transaction-description"><strong>{e.kind === 'addition' ? 'Thêm tiền' : e.category}</strong><p>{e.note || 'Không có ghi chú'}</p></div><strong className={e.kind === 'addition' ? 'positive' : ''}>{e.kind === 'addition' ? '+' : '−'}{vnd(e.amount)}</strong><button className="icon-button" aria-label="Sửa khoản tiền" onClick={() => { setEdit(e); setForm(e.kind); }}><Pencil size={16} /></button></div>)}</section>)}</div> : <Empty icon={Wallet} title="Chưa có giao dịch phù hợp">Ghi lại một khoản chi hoặc thêm tiền để bắt đầu.</Empty>}</Panel>{(form === 'expense' || form === 'addition') && <EntryForm entry={edit} kind={form} month={month} onClose={() => setForm(null)} />} {form === 'budget' && <Modal title="Tiền đầu tháng của Mihu" onClose={() => setForm(null)}><form onSubmit={async e => { e.preventDefault(); try { await save({ type: 'budget.set', month, amount: Number(new FormData(e.currentTarget).get('amount')) }); setForm(null); } catch (e) { setError((e as Error).message); } }}><label className="field">Số tiền (VNĐ)<input name="amount" type="number" inputMode="numeric" required min={0} max={1000000000000} step={1} defaultValue={f.initial ?? undefined} autoFocus /></label><p className="support-line">Những khoản được cho thêm sẽ ghi bằng nút “Thêm tiền”.</p>{error && <p className="error-banner">{error}</p>}<div className="form-actions"><Submit /></div></form></Modal>}{form === 'categories' && <Modal title="Danh mục chi tiêu" onClose={() => setForm(null)}><form onSubmit={async e => { e.preventDefault(); try { await save({ type: 'categories.set', categories: String(new FormData(e.currentTarget).get('categories')).split('\n').map(s => s.trim()).filter(Boolean) }); setForm(null); } catch (e) { setError((e as Error).message); } }}><label className="field">Mỗi danh mục một dòng<textarea name="categories" rows={8} defaultValue={state.categories.join('\n')} required /></label><p className="support-line">Danh mục đã có khoản chi cần được giữ lại.</p>{error && <p className="error-banner">{error}</p>}<div className="form-actions"><Submit /></div></form></Modal>}</div>;
}
function EntryForm({ entry, kind, month, onClose }: { entry?: Entry; kind: Entry['kind']; month: string; onClose: () => void }) { const { state, today, save, busy } = useApp(); const [id] = useState(entry?.id || uid); const [error, setError] = useState(''); return <Modal title={kind === 'expense' ? 'Ghi một khoản chi' : 'Thêm tiền vào tháng'} onClose={onClose}><form onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); try { await save({ type: 'entry.save', entry: { id, kind, date: String(f.get('date')), amount: Number(f.get('amount')), category: kind === 'expense' ? String(f.get('category')) : '', note: String(f.get('note') || '') } }); onClose(); } catch (e) { setError((e as Error).message); } }}><label className="field">Số tiền (VNĐ)<input autoFocus type="number" inputMode="numeric" name="amount" required min={1} max={1000000000000} step={1} defaultValue={entry?.amount} /></label><div className="form-grid"><label className="field">Ngày<input type="date" name="date" required defaultValue={entry?.date || (today.startsWith(month) ? today : month + '-01')} /></label>{kind === 'expense' && <label className="field">Dùng cho<SoftSelect name="category" defaultValue={entry?.category || state.categories[0]}>{state.categories.map(c => <option key={c} value={c}>{c}</option>)}</SoftSelect></label>}</div><label className="field">Ghi chú<textarea name="note" maxLength={4000} defaultValue={entry?.note} placeholder={kind === 'expense' ? 'Một chút chi tiết về khoản chi…' : 'Ví dụ: được cho thêm tiền…'} /></label>{error && <p role="alert" className="error-banner">{error}</p>}<div className="form-actions">{entry && <button type="button" className="button danger" disabled={busy} onClick={async () => { if (!await askConfirmation('Xóa khoản tiền này?')) return; try { await save({ type: 'entry.delete', id }); onClose(); } catch (e) { setError((e as Error).message); } }}><Trash2 size={16} />Xóa</button>}<Submit /></div></form></Modal>; }
function Goals() { const { state, today } = useApp(); const [period, setPeriod] = useState<'week' | 'month'>('week'); const [history, setHistory] = useState(false); const [editing, setEditing] = useState<Goal | null | undefined>(); const goals = state.goals.filter(g => g.period === period && (history ? g.end < today : g.end >= today)); return <div className="stack"><div className="toolbar"><div className="segmented"><button className={period === 'week' ? 'active' : ''} onClick={() => setPeriod('week')}>Mục tiêu tuần</button><button className={period === 'month' ? 'active' : ''} onClick={() => setPeriod('month')}>Mục tiêu tháng</button></div><div className="row wrap"><button className="button" onClick={() => setHistory(!history)}>{history ? 'Đang thực hiện' : 'Xem lịch sử'}</button><button className="button primary" onClick={() => setEditing(null)}><Plus size={17} />Thêm mục tiêu</button></div></div><div className="goal-grid">{goals.map(g => { const percent = goalProgress(state, g); return <Panel key={g.id} title={g.title} action={<button className="icon-button" aria-label={'Sửa ' + g.title} onClick={() => setEditing(g)}><Pencil size={17} /></button>}><span className={'goal-icon ' + (percent === 100 ? 'green' : 'pink')}><Target size={28} /></span><p>{g.note}</p><small>{dateLabel(g.start, true)} – {dateLabel(g.end, true)}</small><div className="row spread progress-label"><span>{percent === 100 ? 'Mihu làm được rồi!' : 'Từng bước một'}</span><strong>{percent}%</strong></div><Progress value={percent} />{g.taskIds.length ? <p className="support-line">Tự cập nhật theo các công việc được liên kết.</p> : g.milestones.length ? <ul className="milestone-list">{g.milestones.map(m => <li key={m.id}><CheckCircle2 size={17} className={m.done ? 'positive' : ''} /><span>{m.title}</span></li>)}</ul> : <p className="support-line">Mở mục tiêu để đánh dấu hoàn thành.</p>}<button className="text-button" onClick={() => setEditing(g)}>Cập nhật tiến độ</button></Panel>; })}</div>{!goals.length && <Panel><Empty icon={Target} title={history ? 'Chưa có mục tiêu trong lịch sử' : 'Một mong muốn nhỏ cũng đáng bắt đầu'} action={!history && <button className="button primary" onClick={() => setEditing(null)}><Plus size={17} />Tạo mục tiêu đầu tiên</button>}>{history ? 'Những mục tiêu đã qua sẽ được giữ lại ở đây.' : 'Mihu muốn dành tuần này cho điều gì?'}</Empty></Panel>}{editing !== undefined && <GoalForm goal={editing || undefined} period={period} onClose={() => setEditing(undefined)} />}</div>; }
function GoalForm({ goal, period, onClose }: { goal?: Goal; period: 'week' | 'month'; onClose: () => void }) { const { state, today, save, busy } = useApp(); const [id] = useState(goal?.id || uid); const [milestones, setMilestones] = useState(goal?.milestones || []); const [linked, setLinked] = useState(goal?.taskIds || []); const [error, setError] = useState(''); const start = period === 'week' ? weekStart(today) : today.slice(0, 7) + '-01'; const end = period === 'week' ? addDays(start, 6) : addDays(shiftMonth(today.slice(0, 7), 1) + '-01', -1); return <Modal title={goal ? 'Chăm chút mục tiêu' : 'Một mục tiêu mới'} onClose={onClose}><form onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); try { await save({ type: 'goal.save', goal: { id, title: String(f.get('title')), note: String(f.get('note') || ''), period: goal?.period || period, start: String(f.get('start')), end: String(f.get('end')), milestones, taskIds: linked, done: f.get('done') === 'on' } }); onClose(); } catch (e) { setError((e as Error).message); } }}><label className="field">Mục tiêu của Mihu<input name="title" required maxLength={200} defaultValue={goal?.title} autoFocus /></label><div className="form-grid"><label className="field">Từ ngày<input name="start" type="date" defaultValue={goal?.start || start} required /></label><label className="field">Đến ngày<input name="end" type="date" defaultValue={goal?.end || end} required /></label></div><label className="field">Vì sao điều này quan trọng?<textarea name="note" maxLength={4000} defaultValue={goal?.note} /></label><h3>Các bước nhỏ</h3><div className="milestones-edit">{milestones.map((m, i) => <div className="row" key={m.id}><input type="checkbox" aria-label={'Hoàn thành ' + m.title} checked={m.done} onChange={e => setMilestones(ms => ms.map((x, j) => j === i ? { ...x, done: e.target.checked } : x))} /><input aria-label={'Bước ' + (i + 1)} value={m.title} maxLength={200} required onChange={e => setMilestones(ms => ms.map((x, j) => j === i ? { ...x, title: e.target.value } : x))} /><button type="button" className="icon-button" aria-label="Xóa bước" onClick={() => setMilestones(ms => ms.filter((_, j) => i !== j))}><X size={16} /></button></div>)}</div><button type="button" className="text-button" onClick={() => setMilestones(ms => [...ms, { id: uid(), title: '', done: false }])}><Plus size={16} />Thêm bước nhỏ</button>{state.tasks.length > 0 && <details><summary>Hoặc liên kết với các việc trong lịch</summary><div className="linked-tasks">{state.tasks.filter(t => !t.until || t.until >= t.date).map(t => <label key={t.id} className="check-label"><input type="checkbox" checked={linked.includes(t.id)} onChange={e => setLinked(v => e.target.checked ? [...v, t.id] : v.filter(id => id !== t.id))} />{t.title}</label>)}</div><p className="support-line">Khi có liên kết, tiến độ tính từ việc trong khoảng ngày của mục tiêu.</p></details>}{!linked.length && !milestones.length && <label className="check-label"><input type="checkbox" name="done" defaultChecked={goal?.done} />Mihu đã hoàn thành mục tiêu này</label>}{error && <p className="error-banner" role="alert">{error}</p>}<div className="form-actions">{goal && <button type="button" className="button danger" disabled={busy} onClick={async () => { if (!await askConfirmation('Xóa mục tiêu này?')) return; try { await save({ type: 'goal.delete', id }); onClose(); } catch (e) { setError((e as Error).message); } }}>Xóa mục tiêu</button>}<Submit /></div></form></Modal>; }
function Journal() { const { state, today, save, busy } = useApp(); const [date, setDate] = useState(today); const [mood, setMood] = useState(state.journals[today]?.mood || 'Ổn'); const [text, setText] = useState(''); const [error, setError] = useState(''); const [dirty, setDirty] = useState(false); async function pick(d: string) { if (dirty && !await askConfirmation('Nội dung chưa lưu. Mihu muốn chuyển ngày và bỏ thay đổi này?')) return; setDate(d); setMood(state.journals[d]?.mood || 'Ổn'); setText(state.journals[d]?.text || ''); setDirty(false); setError(''); } return <div className="journal-grid"><Panel title="Giữ lại một chút hôm nay" action={<Flower />}><form onSubmit={async e => { e.preventDefault(); try { setError(''); if (state.journals[date] && !await askConfirmation('Ngày này đã có nhật ký. Mihu muốn thay thế nội dung đã lưu?')) return; await save({ type: 'journal.save', date, mood: mood as 'Ổn', text }); setText(''); setMood('Ổn'); setDirty(false); } catch (e) { setError((e as Error).message); } }}><label className="field">Ngày của trang nhật ký<input type="date" required value={date} max={today} onChange={e => { if (e.target.value) pick(e.target.value); }} /></label><h3>Hôm nay Mihu cảm thấy…</h3><div className="mood-picker">{['Vui', 'Ổn', 'Bình thường', 'Mệt', 'Buồn'].map((m, i) => <button key={m} type="button" aria-pressed={mood === m} className={mood === m ? 'selected' : ''} onClick={() => { setMood(m); setDirty(true); }}><span>{['😊', '🙂', '😐', '😴', '😔'][i]}</span>{m}</button>)}</div><label className="field">Vài dòng cho Mihu<textarea className="journal-paper" rows={10} maxLength={10000} value={text} onChange={e => { setText(e.target.value); setDirty(true); }} placeholder={'Điều khiến Mihu vui hôm nay…\nMột việc nhỏ Mihu đã làm được…\nNgày mai Mihu muốn thử điều gì?'} /></label><small>{text.length}/10.000 ký tự · Chỉ Mihu của tài khoản này đọc được.</small>{error && <p className="error-banner" role="alert">{error}</p>}<div className="form-actions">{state.journals[date] && <button type="button" disabled={busy} className="button danger" onClick={async () => { if (!await askConfirmation('Xóa trang nhật ký này?')) return; try { await save({ type: 'journal.delete', date }); setText(''); setDirty(false); } catch (e) { setError((e as Error).message); } }}>Xóa trang</button>}<button type="submit" className="button primary" disabled={busy || !dirty}>{busy ? 'Đang lưu…' : 'Lưu một ngày'}</button></div></form></Panel><Panel title="Những ngày đã qua">{Object.keys(state.journals).length ? <div className="journal-history">{Object.entries(state.journals).sort(([a], [b]) => b.localeCompare(a)).map(([d, j]) => <button key={d} className={d === date ? 'selected' : ''} onClick={() => pick(d)}><span className="row spread"><strong>{dateLabel(d, true)}</strong><span className="pill">{j.mood}</span></span><p>{j.text || 'Một cảm xúc đã được lưu lại.'}</p></button>)}</div> : <Empty icon={BookOpen} title="Chưa có trang nhật ký">Không cần viết hay. Chỉ cần là điều Mihu muốn nhớ.</Empty>}</Panel></div>; }
function Account({ user, logout, openNotifications }: { user: User | null; logout: () => void; openNotifications: () => void }) { const { state } = useApp(); return <div className="stack"><section className="welcome-banner account-banner"><div><span className="eyebrow">GÓC RIÊNG CỦA MIHU</span><h2>Một nơi thuộc về Mihu.</h2><p>Những kế hoạch, kỷ niệm và điều nhỏ xinh<br />đều được giữ trong góc riêng này.</p></div><div className="banner-flowers"><Flower /><Flower /></div></section><div className="account-grid"><Panel title="Thông tin tài khoản"><div className="profile"><span className="avatar large">{state.settings.avatar ? <img src={asset(state.settings.avatar)} alt="Ảnh đại diện" /> : 'M'}</span><div><h2>Mihu</h2><p>Góc nhỏ của Mihu</p></div></div><dl className="account-details"><div><dt>Tài khoản đăng nhập</dt><dd>{user?.identity || 'Chưa đăng nhập'}</dd></div><div><dt>Số điện thoại</dt><dd>{user?.phone || '—'}</dd></div><div><dt>Email đăng nhập</dt><dd>{user?.email || 'Chưa kết nối'}</dd></div><div><dt>Tên hiển thị</dt><dd>Mihu</dd></div></dl><p className="support-line"><ShieldCheck size={16} />Dữ liệu được lưu riêng cho từng tài khoản.</p></Panel><div className="stack"><Panel title="Đăng nhập & bảo mật"><p>Mihu đăng nhập bằng liên kết gửi đến email đã đăng ký, không cần mật khẩu. Phiên đăng nhập được giữ trên thiết bị này; khi cần đăng nhập lại, Mihu yêu cầu một liên kết mới.</p><button className="text-button danger" onClick={logout}><LogOut size={17} />Đăng xuất trên thiết bị này</button></Panel><Panel title="Nhắc việc & ứng dụng"><p>Mang lên màn hình chính để mở nhanh hơn mỗi ngày.</p><button className="text-button" onClick={openNotifications}><Bell size={17} />Cài đặt nhắc việc</button><div className="install-tip"><strong>Trên iPhone</strong><p>Mở bằng Safari → Chia sẻ → Thêm vào Màn hình chính → bật mở dưới dạng ứng dụng nếu có.</p><p>Nếu email mở liên kết sang Safari, Mihu có thể yêu cầu liên kết mới, sao chép rồi dán ở màn hình đăng nhập của ứng dụng.</p><small>Trên máy tính, Mihu tiếp tục dùng ngay trong trình duyệt.</small></div></Panel></div></div></div>; }

function Personalize() {
    const { state, save, preview, busy, setSettingsPreview } = useApp(); const [draft, setDraft] = useState<Settings>(state.settings); const [error, setError] = useState(''); const [uploading, setUploading] = useState(false); const dirty = JSON.stringify(draft) !== JSON.stringify(state.settings); useEffect(() => { setSettingsPreview(draft); return () => setSettingsPreview(null); }, [draft, setSettingsPreview]);
    async function upload(file: File, slot: 'avatar' | 'cover' | 'photos', index?: number) { if (preview) throw Error('Hãy đăng nhập để lưu ảnh riêng của Mihu.'); setUploading(true); try { const f = new FormData(); f.set('file', file); const r = await fetch('/api/assets', { method: 'POST', body: f }); const data = await r.json() as { id: string; error?: string }; if (!r.ok) throw Error(data.error || 'Chưa tải được ảnh.'); setDraft(d => { if (slot !== 'photos') return { ...d, [slot]: data.id }; const photos = [...d.photos]; if (index !== undefined) photos[index] = data.id; else if (photos.length < 6) photos.push(data.id); return { ...d, photos }; }); } finally { setUploading(false); } }
    return <form className="stack" onSubmit={async e => { e.preventDefault(); try { await save({ type: 'settings.save', settings: draft }); setError(''); } catch (e) { setError((e as Error).message); } }}><div className="settings-grid"><Panel title="Màu sắc & cảm hứng"><label className="field">Điểm nhấn<SoftSelect value={draft.accent} onChange={e => setDraft({ ...draft, accent: e.target.value as Settings['accent'] })}><option value="pink">Hồng nhạt</option><option value="yellow">Vàng nắng</option></SoftSelect></label><label className="field">Giao diện<SoftSelect value={draft.theme} onChange={e => setDraft({ ...draft, theme: e.target.value as Settings['theme'] })}><option value="light">Sáng</option><option value="dark">Tối</option><option value="system">Theo thiết bị</option></SoftSelect></label><p className="support-line">Màu đang được xem trước. Bấm Lưu thay đổi để giữ lại cho lần sau.</p><label className="field">Lời nhắn cho Mihu<textarea value={draft.quote} maxLength={300} onChange={e => setDraft({ ...draft, quote: e.target.value })} /></label></Panel><Panel title="Khung ảnh của Mihu">{(['avatar', 'photos'] as const).map(slot => <PhotoPicker key={slot} label={slot === 'avatar' ? 'Ảnh đại diện' : 'Ảnh trang trí'} ids={slot === 'photos' ? draft.photos : draft[slot] ? [draft[slot]] : []} limit={slot === 'photos' ? 6 : 1} onSave={(file, index) => upload(file, slot, index)} onRemove={id => setDraft(d => ({ ...d, [slot]: slot === 'photos' ? d.photos.filter(x => x !== id) : '' }))} />)}<p className="support-line">Tối đa 6 ảnh trang trí. Dashboard hiển thị 2 ảnh và chọn cặp ảnh ngẫu nhiên mỗi phút. Bấm vào ảnh để thay và căn lại.</p></Panel><Panel title="Những khung Mihu muốn thấy">{[['tasks', 'Việc hôm nay'], ['week', 'Nhịp tuần'], ['finance', 'Chi tiêu'], ['goals', 'Mục tiêu'], ['journal', 'Nhật ký'], ['photos', 'Góc ảnh']].map(([id, label]) => <label className="check-label" key={id}><input type="checkbox" checked={!draft.hidden.includes(id)} onChange={e => setDraft(d => ({ ...d, hidden: e.target.checked ? d.hidden.filter(x => x !== id) : [...d.hidden, id] }))} />{label}</label>)}</Panel></div>{error && <p className="error-banner" role="alert">{error}</p>}<div className="settings-save-bar"><span>{uploading ? 'Đang tải ảnh…' : dirty ? 'Có thay đổi chưa lưu' : 'Đã lưu'}</span><div className="row"><button type="button" className="button" disabled={busy || uploading || !dirty} onClick={async () => { if (await askConfirmation('Bỏ các thay đổi và trở về cài đặt đã lưu?')) setDraft(state.settings); }}>Hủy</button><button type="submit" className="button primary" disabled={busy || uploading || !dirty}>{busy ? 'Đang lưu…' : 'Lưu thay đổi'}</button></div></div></form>;
}

function Notifications() { const { state, today, preview } = useApp(); const [status, setStatus] = useState(''); const [busy, setBusy] = useState(false); const upcoming = daysBetween(today, addDays(today, 6)).flatMap(d => tasksOn(state, d)).filter(t => t.reminder >= 0 && !t.done); async function enable() { if (preview) { setStatus('Hãy đăng nhập để bật nhắc việc.'); return; } setBusy(true); try { const { enablePush } = await import('@/lib/push-client'); await enablePush(); setStatus('Đã bật nhắc việc trên thiết bị này.'); } catch (e) { setStatus((e as Error).message); } finally { setBusy(false); } } return <div className="stack"><p>Bật thông báo trên thiết bị này để Mihu nhận lời nhắc khi đã đóng web.</p><p className="notice">Trên iPhone, hãy thêm Mihu’s Corner vào Màn hình chính, mở từ biểu tượng đó rồi bật thông báo. Chế độ Tập trung hoặc mất mạng có thể làm thông báo đến muộn.</p><div className="row wrap"><button className="button primary" disabled={busy} onClick={enable}><Bell size={17} />{busy ? 'Đang kết nối…' : 'Bật nhắc việc'}</button><button className="button" disabled={busy || preview} onClick={async () => { try { await api('/api/push', { action: 'disable' }); setStatus('Đã tắt nhắc việc trên thiết bị này.'); } catch (e) { setStatus((e as Error).message); } }}>Tắt trên thiết bị này</button></div>{status && <p role="status" className="notice">{status}</p>}<h3>Sắp nhắc trong 7 ngày tới</h3>{upcoming.length ? upcoming.map(t => <div className="reminder-row" key={t.key}><Clock size={18} /><div><strong>{t.title}</strong><p>{dateLabel(t.occurrenceDate, true)} · {t.time} · {t.reminder === 0 ? 'Đúng giờ' : `Trước ${t.reminder} phút`}</p></div></div>) : <p>Chưa có việc nào đặt lời nhắc.</p>}</div>; }

